Q() { docker exec -i xnova-database psql -U postgres -d postgres -At -c "$1" < /dev/null; }
echo "== constraints"
Q "SELECT conrelid::regclass||' '||conname||' '||pg_get_constraintdef(oid) FROM pg_constraint WHERE conrelid IN ('public.jackpot_history'::regclass,'public.referral_commissions'::regclass,'public.admin_revenue'::regclass,'public.fleet_ships'::regclass,'public.planet_defenses'::regclass,'public.planet_ships'::regclass,'public.ship_types'::regclass) ORDER BY 1"
echo "== cron"
Q "SELECT jobid||' | '||jobname||' | '||schedule||' | '||command FROM cron.job ORDER BY jobid"
echo "== ship_types images"
Q "SELECT id||' | '||code||' | '||name||' | '||category||' | '||COALESCE(image_url,'NULL') FROM ship_types ORDER BY id"
echo "== ship_types full colony"
Q "SELECT row_to_json(s) FROM ship_types s WHERE code IN ('colony_ship','small_cargo')"
echo "== defense types"
Q "SELECT id||' | '||code||' | '||name||' | '||COALESCE(max_per_planet::text,'-') FROM defense_types ORDER BY id"
echo "== fns"
Q "SELECT p.oid::regprocedure FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('galaxy_navigate','purchase_instant_unit','refill_colony_resources','update_production_percentages','secure_demolish_building','purchase_supply_box','launch_missiles','deploy_to_fortress','create_market_listing','purchase_market_listing','fulfill_buy_offer','create_colony_listing','purchase_colony_listing','secure_abandon_colony','sync_planet_resources','update_planet_resources','calculate_planet_resources','recall_deployed_fleet','cancel_fleet','get_user_planets','accelerate_fleet_v2','create_buy_offer','auto_cancel_insufficient_listings','set_planet_autopilot_enabled','process_user_pending_fleets','instant_complete_building','instant_complete_shipyard','instant_complete_shipyard_item','secure_start_research','secure_add_to_building_queue','secure_activate_building_queue','jump_gate_transfer','use_jump_gate') ORDER BY 1"
echo "== market_listings cols"
Q "SELECT string_agg(column_name||':'||data_type, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='market_listings'"
echo "== profiles cols"
Q "SELECT string_agg(column_name, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='profiles'"
echo "== planets cols"
Q "SELECT string_agg(column_name||':'||data_type, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='planets'"
echo "== battle_reports cols"
Q "SELECT string_agg(column_name||':'||data_type, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='battle_reports'"
echo "== messages cols"
Q "SELECT string_agg(column_name||':'||data_type, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='messages'"
echo "== debris cols"
Q "SELECT table_name||': '||string_agg(column_name||':'||data_type, ', ' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name IN ('debris_fields') GROUP BY table_name"
echo "== fleet triggers"
Q "SELECT tgrelid::regclass||' '||tgname||' '||pg_get_triggerdef(oid) FROM pg_trigger WHERE NOT tgisinternal AND tgrelid IN ('public.fleets'::regclass,'public.fleet_ships'::regclass,'public.planets'::regclass,'public.planet_resources'::regclass,'public.planet_defenses'::regclass) ORDER BY 1"
echo "== srr"
Q "SELECT rolname, rolsuper FROM pg_roles WHERE rolname IN ('postgres','supabase_admin','authenticated')"
echo "== realtime pub"
Q "SELECT tablename FROM pg_publication_tables WHERE pubname='supabase_realtime' ORDER BY 1"
